  ) AS t(dest_id, destination, maps_dropping_point_id, dropping_point, poi_lat, poi_long, dp_lat, dp_lon)
),

poi_dp_distance AS (
  SELECT
    dest_id,
    destination,
    maps_dropping_point_id,
    6371.0 * 2 * ASIN(
      SQRT(
        POWER(SIN(RADIANS(dp_lat - poi_lat) / 2), 2)
        + COS(RADIANS(poi_lat)) * COS(RADIANS(dp_lat))
          * POWER(SIN(RADIANS(dp_lon - poi_long) / 2), 2)
      )
    ) AS distance_km
  FROM poi_dp_base
),

dp_distance_dedup AS (
  SELECT
    dest_id,
    MAX(destination) AS destination,
    maps_dropping_point_id,
    MIN(distance_km) AS distance_km
  FROM poi_dp_distance
  GROUP BY dest_id, maps_dropping_point_id
),

dp_in_range AS (
  SELECT
    dest_id,
    destination,
    maps_dropping_point_id,
    distance_km,
    distance_km < 1 AS within_1_km,
    distance_km < 3 AS within_3_km,
    distance_km < 5 AS within_5_km
  FROM dp_distance_dedup
),

city_routes AS (
  SELECT DISTINCT
    inv.destinationid AS dest_id,
    inv.routeid AS route_id
  FROM inventory.inventory_snapshot inv
  CROSS JOIN params p
  WHERE inv.dateofjourney = p.inventory_doj
    AND inv.destinationid IN (SELECT DISTINCT dest_id FROM poi_dp_base)
    AND inv.routeid IS NOT NULL
),

route_destination_dps AS (
  SELECT DISTINCT
    rdp.destination_id AS dest_id,
    rdp.route_id,
    rdp.dropping_point_id AS maps_dropping_point_id
  FROM inventory.route_dropping_points rdp
  WHERE rdp.destination_id IN (SELECT DISTINCT dest_id FROM poi_dp_base)
    AND rdp.dropping_point_id IS NOT NULL
    AND rdp.route_id IS NOT NULL
),

route_min_distance AS (
  SELECT
    cr.dest_id,
    cr.route_id,
    MIN(dir.distance_km) AS min_dp_distance_km
  FROM city_routes cr
  LEFT JOIN route_destination_dps rd
    ON cr.dest_id = rd.dest_id
   AND cr.route_id = rd.route_id
  LEFT JOIN dp_in_range dir
    ON rd.dest_id = dir.dest_id
   AND rd.maps_dropping_point_id = dir.maps_dropping_point_id
  GROUP BY cr.dest_id, cr.route_id
),

route_coverage AS (
  SELECT
    dest_id,
    COUNT(DISTINCT route_id) AS total_route_ids,
    COUNT(DISTINCT CASE WHEN min_dp_distance_km < 1 THEN route_id END) AS route_ids_within_1_km,
    COUNT(DISTINCT CASE WHEN min_dp_distance_km < 3 THEN route_id END) AS route_ids_within_3_km,
    COUNT(DISTINCT CASE WHEN min_dp_distance_km < 5 THEN route_id END) AS route_ids_within_5_km
  FROM route_min_distance
  GROUP BY dest_id
),

confirmed_transactions AS (
  SELECT
    b.destination_location_id AS dest_id,
    b.route_id,
    b.tin,
    b.dst_location_id AS maps_dropping_point_id
  FROM transaction.bus_ticket_events b
  CROSS JOIN params p
  WHERE b.date_of_issue >= p.txn_start
    AND b.date_of_issue < p.txn_end
    AND b.country_code = 'IND'
    AND b.event_class = 2
    AND b.event_type = 101
    AND b.tin IS NOT NULL
    AND TRIM(CAST(b.tin AS VARCHAR)) NOT IN ('', 'null')
    AND b.destination_location_id IN (SELECT DISTINCT dest_id FROM poi_dp_base)
),

txn_with_distance AS (
  SELECT
    t.dest_id,
    t.route_id,
    t.tin,
    t.maps_dropping_point_id,
    dir.distance_km
  FROM confirmed_transactions t
  LEFT JOIN dp_in_range dir
    ON t.dest_id = dir.dest_id
   AND t.maps_dropping_point_id = dir.maps_dropping_point_id
),

transaction_coverage AS (
  SELECT
    dest_id,
    COUNT(DISTINCT tin) AS total_transactions,
    COUNT(DISTINCT CASE WHEN distance_km < 1 THEN tin END) AS transactions_within_1_km,
    COUNT(DISTINCT CASE WHEN distance_km < 3 THEN tin END) AS transactions_within_3_km,
    COUNT(DISTINCT CASE WHEN distance_km < 5 THEN tin END) AS transactions_within_5_km,
    COUNT(DISTINCT CASE WHEN distance_km IS NULL THEN tin END) AS transactions_without_dp_distance
  FROM txn_with_distance
  GROUP BY dest_id
),

city_dim AS (
  SELECT dest_id, MAX(destination) AS destination
  FROM poi_dp_base
  GROUP BY dest_id
)

SELECT
  c.dest_id,
  c.destination,
  COALESCE(rc.total_route_ids, 0) AS total_route_ids,
  COALESCE(rc.route_ids_within_1_km, 0) AS route_ids_within_1_km,
  COALESCE(rc.route_ids_within_3_km, 0) AS route_ids_within_3_km,
  COALESCE(rc.route_ids_within_5_km, 0) AS route_ids_within_5_km,
  ROUND(100.0 * COALESCE(rc.route_ids_within_1_km, 0) / NULLIF(COALESCE(rc.total_route_ids, 0), 0), 2) AS route_coverage_pct_1_km,
  ROUND(100.0 * COALESCE(rc.route_ids_within_3_km, 0) / NULLIF(COALESCE(rc.total_route_ids, 0), 0), 2) AS route_coverage_pct_3_km,
  ROUND(100.0 * COALESCE(rc.route_ids_within_5_km, 0) / NULLIF(COALESCE(rc.total_route_ids, 0), 0), 2) AS route_coverage_pct_5_km,
  COALESCE(tc.total_transactions, 0) AS total_transactions,
  COALESCE(tc.transactions_within_1_km, 0) AS transactions_within_1_km,
  COALESCE(tc.transactions_within_3_km, 0) AS transactions_within_3_km,
  COALESCE(tc.transactions_within_5_km, 0) AS transactions_within_5_km,
  COALESCE(tc.transactions_without_dp_distance, 0) AS transactions_without_dp_distance,
  ROUND(100.0 * COALESCE(tc.transactions_within_1_km, 0) / NULLIF(COALESCE(tc.total_transactions, 0), 0), 2) AS transaction_coverage_pct_1_km,
  ROUND(100.0 * COALESCE(tc.transactions_within_3_km, 0) / NULLIF(COALESCE(tc.total_transactions, 0), 0), 2) AS transaction_coverage_pct_3_km,
  ROUND(100.0 * COALESCE(tc.transactions_within_5_km, 0) / NULLIF(COALESCE(tc.total_transactions, 0), 0), 2) AS transaction_coverage_pct_5_km
FROM city_dim c
LEFT JOIN route_coverage rc ON c.dest_id = rc.dest_id
LEFT JOIN transaction_coverage tc ON c.dest_id = tc.dest_id
ORDER BY c.destination;
